+        }),
+      );
+      expect(result).toMatchObject({ id: commentId, body, editedAt: expect.any(Date) });
+    });
+  });
+
+  describe('getArticles', () => {
+    beforeEach(() => {
+      // @ts-ignore
+      prismaMock.article.count.mockResolvedValue(0);
+      // @ts-ignore
+      prismaMock.article.findMany.mockResolvedValue([]);
+    });
+
+    test('should cap take at 50 when the limit is above 50', async () => {
+      // Given
+      const query = { limit: '500' };
+
+      // When
