+
+      // Then
+      expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
+        expect.objectContaining({ take: 20 }),
+      );
+    });
+
+    test('should allow a limit of exactly 50', async () => {
+      // Given
+      const query = { limit: '50' };
+
+      // When
+      await getArticles(query);
+
+      // Then
+      expect(prismaMock.article.findMany).toHaveBeenLastCalledWith(
+        expect.objectContaining({ take: 50 }),
+      );
+    });
+
+    test('should default take to 10 when no limit is given', async () => {
+      // Given
+      const query = {};
+
+      // When
